#!/bin/bash
# IMAGE-FILE mode test: PATH-shimmed losetup/mount/umount. The
# "loop device" is the inert real node /dev/loop0; NO real image, loop
# attach or mount happens.
set -u
HERE=$(cd "$(dirname "$0")" && pwd)
P=$(cd "$HERE/.." && pwd)/pi_clean.sh
# shared rootfs fixture (regenerated by make_base_fix.sh when missing)
[[ -e /tmp/pi_clean_test/base_fix/etc/os-release ]] || bash "$HERE/make_base_fix.sh"
SHIM=/tmp/pi_clean_test/shim_loop
LOG=/tmp/pi_clean_test/shim_loop.log
FAKEIMG=/tmp/pi_clean_test/fakeimage.img
STAGE=/tmp/pi_clean_test/dev_stage
export SHIM_LOG="$LOG"

rm -rf "$SHIM"; mkdir -p "$SHIM"
rm -rf "$STAGE"
mkdir -p "$STAGE"
cp -a /tmp/pi_clean_test/base_fix/. "$STAGE/"     # content = a plausible rootfs
printf 'x' > "$FAKEIMG"                      # content irrelevant: losetup is shimmed
: > "$LOG"

cat > "$SHIM/losetup" <<'EOF'
#!/bin/bash
echo "losetup $*" >> "${SHIM_LOG:?}"
# losetup -d DEV
case $* in -d*) exit 0 ;; esac
# losetup -fP --show FILE
[[ -n ${SHIM_FAILALL:-} ]] && exit 1
echo /dev/loop0
EOF
cat > "$SHIM/mount" <<'EOF'
#!/bin/bash
dev=$3; mp=$4
[[ $dev == /dev/loop0 ]] || exit 32
cp -a ${SHIM_STAGE}/. "$mp/"
exit 0
EOF
# emulate a REAL umount: the "filesystem" (the staged content the sim
# `mount` copied into the mount point) comes off; the mount-point dir
# itself stays (as with a real umount) so the script's rmdir succeeds
cat > "$SHIM/umount" <<'EOF'
#!/bin/bash
mp=${1:-}
# GNU rm refuses "dir/." — find -delete empties the dir, keeps the dir itself
[[ -n $mp && -d $mp ]] && find "$mp" -mindepth 1 -delete 2>/dev/null
exit 0
EOF
export SHIM_STAGE="$STAGE"
chmod +x "$SHIM/losetup" "$SHIM/mount" "$SHIM/umount"

t() { desc=$1; want=$2; shift 2
    out=$(PATH="$SHIM:$PATH" "$@" 2>&1); rc=$?
    if [[ $rc == "$want" ]]; then echo "PASS (rc=$rc): $desc"; else echo "FAIL (rc=$rc want=$want): $desc"; printf '%s\n' "$out" | head -5; return 1; fi
}

echo A=file-total;      t "-t on an image file"     0 bash "$P" "$FAKEIMG" -t
tot=$(PATH="$SHIM:$PATH" bash "$P" "$FAKEIMG" -t 2>/dev/null)
[[ "$tot" == "2097162" ]] && echo "PASS: -t number correct ($tot)" || echo "FAIL: -t number ($tot)"
hdr=$(PATH="$SHIM:$PATH" bash "$P" "$FAKEIMG" -n 2>/dev/null < <(printf 'n\n'))
[[ "$hdr" == *"— image /tmp/pi_clean_test/fakeimage.img"* ]] && echo "PASS: header names the image file" || echo "FAIL: header: $(printf '%s' "$hdr" | head -2)"
echo A=attach-fail;     t "losetup failure -> rc2"   2 env SHIM_FAILALL=1 PATH="$SHIM:$PATH" bash "$P" "$FAKEIMG" -t
failout=$(env SHIM_FAILALL=1 PATH="$SHIM:$PATH" bash "$P" "$FAKEIMG" -t 2>&1 >/dev/null)
[[ "$failout" == *"cannot attach"* && "$failout" == *"not root"* ]] && echo "PASS: attach-failure message" || echo "FAIL: attach message: $failout"
grep -q '^losetup -d /dev/loop0$' "$LOG" && echo "PASS: trap detached the loop device" || { echo "FAIL: no detach in log:"; cat "$LOG"; }
left=$(ls -d /run/pi_clean.* /tmp/pi_clean.* 2>/dev/null)
if [[ -z $left ]]; then echo "PASS: no leftover mount points"
else echo "shim leftovers (expected): $left" | tr '\n' ' '; echo; rm -rf $left; fi
